function floating(name){const object=name==='float-key'?'key':name==='float-ball'?'ball':'wood',draw={wood,key,ball}[object],y=object==='key'?295:object==='ball'?159:177;return '<rect x="74" y="104" width="452" height="235" rx="25" fill="#f6fcfd" stroke="#7dacc2" stroke-width="6"/><path d="M79 181q114-15 221 0 113-15 222 0v132q0 21-21 21H100q-21 0-21-21Z" fill="#9bd6e8"/>'+(name==='water-tray'?'':name==='float-pair'?at(235,177,wood())+at(411,295,key()):at(300,y,moving('water-object','translate(0px,'+(82-y)+'px)','translate(0px,0px)',draw())))+'<path d="M80 181q111-15 220 0 111-15 220 0" stroke="#509cbc" stroke-width="5" fill="none"/>'+(object==='wood'||name==='float-pair'?'<path d="M182 196h108m-30 17h52" stroke="#bfe9f4" stroke-width="4"/>':'');}
const helper=()=>scale(-30,70,.6,face());
function pushing(name){const pull=name.startsWith('pull-');return helper()+'<path d="M190 294h330" stroke="#c5baa4" stroke-width="7" stroke-linecap="round"/>'+(pull?'<line data-science-rope="true" x1="206" y1="225" x2="'+(name==='pull-start'?370:230)+'" y2="232" stroke="#b69268" stroke-width="5"/>'+at(name==='pull-start'?440:300,245,name==='pull-start'?wagon():moving('pull','translate(140px,0px)','translate(0px,0px)',wagon())):at(name==='push-start'?280:440,245,name==='push-start'?toy():moving('push','translate(-160px,0px)','translate(0px,0px)',toy())))+text(405,84,pull?'Pull closer':'Push away',27)+'<path d="'+(pull?'M453 124H303m17-12-17 12 17 12':'M275 124h170m-17-12 17 12-17 12')+'" stroke="#dcaa58" stroke-width="7" fill="none" stroke-linecap="round"/>';}
function magnetic(name){const object=name==='magnet-wood'?'wood':name==='magnet-foil'?'foil':'clip',draw={wood,foil,clip}[object],attracted=object==='clip'&&name!=='magnet-ready';return '<rect x="34" y="288" width="532" height="30" rx="12" fill="#d0b291"/>'+at(153,198,magnet())+(name==='magnet-ready'?text(404,183,'Choose an object',27):at(attracted?270:422,215,attracted?moving('attract','translate(152px,0px)','translate(0px,0px)',draw()):draw()))+text(320,52,attracted?'The steel clip moves':name==='magnet-ready'?'Test our magnet':'This object stays still',24);}
const toggle=(on=false)=>'<g data-science-object="switch"><rect x="-44" y="-62" width="88" height="124" rx="16" fill="#fffae8" stroke="#a4b4bd" stroke-width="4"/><rect x="-24" y="-35" width="48" height="70" rx="8" fill="'+(on?'#abd6a5':'#bdcbd9')+'" stroke="#78919f" stroke-width="3"/><path d="M-21 '+(on?'-27':'26')+'H21" stroke="#fffef5" stroke-width="8" stroke-linecap="round"/></g>';
function lamp(name){const on=name==='lamp-on';return '<rect x="57" y="301" width="488" height="27" rx="12" fill="#d3ae8d"/>'+at(128,203,toggle(on))+(on?'<g data-science-object="lamp-glow" data-science-motion="glow" data-from="scale(.5)" data-to="scale(1)"><path d="m320 152-63 143h281l-74-143Z" fill="#ffe193" opacity=".65"/><circle cx="393" cy="139" r="59" fill="#ffe193" opacity=".4"/></g>':'')+'<path d="M395 170v112m-41 10h84" stroke="#7892af" stroke-width="13" stroke-linecap="round"/><path d="m344 79-32 83h160l-32-83Z" fill="'+(on?'#ffde83':'#a5c2d8')+'" stroke="#708eac" stroke-width="4"/><ellipse cx="392" cy="164" rx="69" ry="14" fill="'+(on?'#fff0ba':'#81a0bb')+'"/>'+(on?'<circle cx="392" cy="168" r="12" fill="#fff6cf"/>':'');}
function content(name){if(name==='sun')return sun(300,175);if(name==='moon')return '<path d="M340 87a93 93 0 1 0 0 176q-124-54 0-176Z" fill="#c8c8e5" stroke="#9d9ebb" stroke-width="4"/>';if(name==='plant')return at(300,235,grass());if(name==='grass-pale'||name==='grass-green')return at(300,231,grass(name==='grass-pale'));if(name.startsWith('plants-'))return plants(name);if(name==='leaf')return at(300,180,leaf());if(name==='river'||name==='cloud'||name.startsWith('rain-')||['water-warm','vapour','vapour-rise','cloud-drops','cloud-form'].includes(name))return waterScene(name);if(name.startsWith('organ-'))return scale(300,177,1.8,organs[name.slice(6)]());if(name.startsWith('body-'))return body(name);if(name.startsWith('sense-'))return senses(name);if(['nest','pond','farm','forest','habitats'].includes(name)||name.startsWith('home-')||name.startsWith('animal-'))return habitat(name);if(name==='earth-pair')return scale(0,64,.48,earth('earth-day'))+scale(300,64,.48,earth('earth-night'));if(name.startsWith('earth-'))return earth(name);if(name==='water-tray'||name.startsWith('float-'))return floating(name);if(name.startsWith('object-'))return scale(300,185,1.8,({wood,key,ball,toy,wagon,clip,foil}[name.slice(7)])());if(name==='push-pull-pair')return scale(0,35,.48,pushing('push-toy'))+scale(300,35,.48,pushing('pull-wagon'));if(name.startsWith('push-')||name.startsWith('pull-'))return pushing(name);if(name==='magnet')return scale(300,186,1.6,magnet());if(name.startsWith('magnet-'))return magnetic(name);if(name==='switch')return at(300,180,toggle());if(name==='lamp-pair')return scale(0,0,.5,lamp('lamp-on'))+scale(300,0,.5,lamp('lamp-off'));if(name.startsWith('lamp-'))return lamp(name);throw Error('Unknown science scene: '+name);}
const labels={plant:'A green plant',sun:'Sunlight',moon:'The Moon',leaf:'A leaf','plants-start':'Two similar green grass patches receive the same soil and water before one is covered','plants-covered':'One patch of green grass is covered by an opaque bowl that blocks sunlight','plants-reveal':'After several days the bowl lifts to reveal pale, weak grass; the sunlight patch stays green','plants-revealed':'After several days: sunlight grass stays green; covered grass is pale and weak','grass-green':'Green grass','grass-pale':'Pale grass, still alive',river:'A river','water-warm':'Sunlight warms river water',vapour:'Dashed arrows represent invisible water vapour above a river','vapour-rise':'Arrows show invisible water vapour rising; no liquid water drops rise','cloud-form':'Cooling water vapour forms tiny water droplets in a cloud','cloud-drops':'Tiny water droplets in a cloud',cloud:'A cloud','rain-river':'Rain drops fall and fill a river','rain-falls':'Rain falls from a cloud to the river','rain-drops':'Rain drops','body-all':'Friendly approximate brain, lungs, heart and stomach positions','body-brain':'Brain in the head','body-heart':'Heart in the chest, slightly to the child’s left','body-lungs':'Two lungs in the chest','body-stomach':'Stomach below the lungs','sense-see':'Child uses eyes to see a butterfly','sense-hear':'Child uses ears to hear a bell','sense-smell':'Child uses nose to smell a flower','sense-taste':'Child tastes an apple with the tongue','sense-touch':'Child feels a soft toy with skin','home-bird':'A bird in a nest','home-frog':'A frog by a pond','home-cow':'A cow by a barn on a farm','home-deer':'A deer among forest trees',habitats:'Bird and nest, frog and pond, cow and farm, deer and forest','earth-day':'Sunlight from the left lights half of Earth; our marked place is on that lit half','earth-night':'Sun stays in the same direction; our marked place has turned to the dark half','earth-turn':'Earth turns; our marked place moves from the sunlit half to the dark half','earth-pair':'Compare a marked place facing toward and away from the Sun','float-wood':'The ordinary dry wooden block floats partly in water at the surface','float-key':'The solid steel key sinks to the bottom','float-ball':'The sealed hollow plastic ball floats at the water surface','float-pair':'Wood block at the water surface; steel key at the bottom','water-tray':'A clear tank of water ready to test an object','object-wood':'Ordinary dry wooden block','object-key':'Solid steel key','object-ball':'Sealed hollow plastic ball','object-clip':'Plain carbon-steel paper clip','object-foil':'Aluminium foil','push-start':'Child and toy before a push','push-toy':'Toy moves away from the child in a push','pull-start':'Child and wagon before a pull','pull-wagon':'Wagon moves toward the child, pulled by a rope','magnet-ready':'Magnet ready for an object test','magnet-clip':'Magnet visibly pulls the plain steel paper clip closer','magnet-wood':'Wooden block stays still beside a magnet','magnet-foil':'Aluminium foil stays still beside this ordinary magnet','lamp-on':'Pretend switch on; lamp glows yellow','lamp-off':'Pretend switch off; lamp has no glow','lamp-pair':'A glowing lamp and an unlit lamp',switch:'A pretend light switch'};
export function scienceScene(name,small=false){return finishIllustration('<svg class="science-scene '+(small?'science-scene-small':'')+'" viewBox="'+(small&&(name.startsWith('object-')||name.startsWith('organ-')||['sense-eyes','sense-ears','sense-nose','sense-tongue','sense-hand','switch'].includes(name))?'140 30 320 300':'0 0 600 360')+'" role="img" aria-label="'+esc(labels[name]||name.replaceAll('-',' '))+'" data-science-scene="'+name+'">'+backdrop()+content(name)+'</svg>');}
export const scienceChoice=c=>scienceScene(c.scene,true)+'<span>'+esc(c.label)+'</span>';
export const scienceMotionScenes=new Set(['plants-reveal','rain-river','rain-falls','vapour-rise','cloud-form','body-brain','body-heart','body-lungs','body-stomach','earth-turn','float-wood','float-key','float-ball','push-toy','pull-wagon','magnet-clip','lamp-on']);
export function animateScienceScene(root){const animations=[],reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let frame;root.querySelectorAll('[data-science-motion]').forEach(el=>{if(reduced)return;const k=el.dataset.scienceMotion,frames=k==='organ'?[{transform:'scale(1)'},{transform:'scale(1.12)'},{transform:'scale(1)'}]:[{transform:el.dataset.from},{transform:el.dataset.to}];const a=el.animate(frames,{duration:k==='turn'?1800:1400,iterations:k==='organ'?2:1,easing:'ease-in-out',fill:'forwards'});animations.push(a);if(k==='pull'){const rope=root.querySelector('[data-science-rope]');const tick=()=>{if(a.playState==='idle')return;const fraction=a.effect.getComputedTiming().progress??0;rope?.setAttribute('x2',String(230+140*(1-fraction)));if(a.playState!=='finished')frame=requestAnimationFrame(tick);};tick();}});return()=>{cancelAnimationFrame(frame);animations.forEach(a=>a.cancel());};}
